INSERT INTO ai_rules (id, rule_text, source_count, active, created_at, updated_at) VALUES
('rule-0001', 'לפנות תמיד בלשון רבים: אתם, שלכם. לעולם לא אתה בלשון יחיד.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0002', 'לתאר מה שעושים ביחד בגוף ראשון רבים עתיד: נשב, נבין, נאפיין, נבנה, נחבר. זה מה שהופך טקסט מברושור לשיחה.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0003', 'להיות קונקרטי: לתאר משימה אמיתית ומוכרת (תזכורת, הודעת מעקב, העברת פרטים בין מערכות) ולא מילה מופשטת כמו תהליכים או פתרונות.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0004', 'קצב המשפטים: פרגמנט קצר אחד או שניים, ואז משפט אחד שמסביר. לא שלושה משפטים ארוכים ברצף.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0005', 'שאלה ככותרת מותרת (מה זה בעצם אומר, נשמע מוכר), אבל לא יותר מפעמיים באותו עמוד.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0006', 'לגוון את מבנה הכותרות בין קטעים ועמודים. לא לחזור על אותה תבנית כמו X אחד. Y: שוב ושוב.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0007', 'קריאה לפעולה היא תמיד הזמנה או פועל, כמו בואו נדבר או לתיאום שיחה. לעולם לא שם עצם באנגלית בתוך קריאה לפעולה בעברית.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0008', 'אסור מקף ארוך (em dash) בשום מקום בטקסט. משתמשים בפסיק, נקודתיים, נקודה, או מנסחים מחדש.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0009', 'אסור שמות ספקים, פלטפורמות או פריימוורקים בקופי הציבורי.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0010', 'אסור להמציא מספרים: אחוזי שיפור, כמות לקוחות, שנות ותק, מחירים, לוחות זמנים או תוצאות. אם המידע לא אושר, לא כותבים אותו.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0011', 'אסור מילים באנגלית בתוך קריאות לפעולה בעברית. CRM ו-AI מותרים כמילים בגוף הטקסט כי כך בעלי עסקים בישראל באמת אומרים אותן.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0012', 'אסור ביטויים שחוקים כמו מייעלים תהליכים, פתרונות מתקדמים, חדשנות, לוקחים את העסק לשלב הבא, וכל ביטוי ששורד גם אם מחליפים את הנושא של המשפט.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0013', 'מותר וכדאי לכתוב בבירור מה דבר מסוים לא עושה, זה בונה אמון. למשל: אוטומציה טובה לא מחליטה במקומכם.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0014', 'אסור לפתוח משפטים במילים כמו בהחלט, באופן כללי, או להלן. אלה מסגירות טקסט שנכתב על ידי AI.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0015', 'אסור קלישאות מתורגמות כמו בואו נצלול לעומק, חשוב לציין ש, או בעולם של היום. הן מסגירות טקסט AI או מתורגם.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0016', 'אסור לכתוב על תהליך הכתיבה עצמו בתוך התוכן, כמו כפי שלמדנו או המדריך ממליץ. זה דוח על העבודה, לא העבודה.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0017', 'אסור לחזור על אותה מילה פעמיים באותו משפט קצר, זה נשמע מתורגם ולא טבעי.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0018', 'אתרים ישראליים ללימוד טון קופי בתחום המערכות והאוטומציה: automotion.co.il, automagic.co.il, avior-ai.co.il, optimate.co.il, smartup.co.il, infines.co.il, olsi.co.il, aran.org.il, locwise.com. לא מעתיקים מהם, לומדים מהם קצב וגובה שפה.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z');
